import heapq

def match(orders):
    buy_heap = []   # entries: (-price, idx, id)
    sell_heap = []  # entries: (price, idx, id)
    order_info = {}  # id -> {'side','price','qty','active','idx'}
    trades = []

    def try_match(side, incoming_id, limit_price, qty, is_market):
        book = sell_heap if side == 'buy' else buy_heap
        while qty > 0 and book:
            key, idx, oid = book[0]
            info = order_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(book)
                continue
            resting_price = key if side == 'buy' else -key
            if not is_market:
                if side == 'buy' and resting_price > limit_price:
                    break
                if side == 'sell' and resting_price < limit_price:
                    break
            trade_qty = min(qty, info['qty'])
            if side == 'buy':
                trades.append([incoming_id, oid, resting_price, trade_qty])
            else:
                trades.append([oid, incoming_id, resting_price, trade_qty])
            qty -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] == 0:
                info['active'] = False
                heapq.heappop(book)
            # else leave it at top, still valid (partially filled, keeps place)
        return qty

    for pos, order in enumerate(orders):
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            info = order_info.get(id_)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'limit':
            _, id_, side, price, qty = order
            remaining = try_match(side, id_, price, qty, False)
            if remaining > 0:
                order_info[id_] = {'side': side, 'price': price, 'qty': remaining,
                                    'active': True, 'idx': pos}
                if side == 'buy':
                    heapq.heappush(buy_heap, (-price, pos, id_))
                else:
                    heapq.heappush(sell_heap, (price, pos, id_))
            else:
                order_info[id_] = {'side': side, 'price': price, 'qty': 0,
                                    'active': False, 'idx': pos}

        elif typ == 'ioc':
            _, id_, side, price, qty = order
            remaining = try_match(side, id_, price, qty, False)
            order_info[id_] = {'side': side, 'price': price, 'qty': remaining,
                                'active': False, 'idx': pos}

        elif typ == 'market':
            _, id_, side, qty = order
            remaining = try_match(side, id_, None, qty, True)
            order_info[id_] = {'side': side, 'price': None, 'qty': remaining,
                                'active': False, 'idx': pos}

    return trades

